def findString(s):
    char_count = {}
    for char in s:
        char_count[char] = char_count.get(char, 0) + 1

    chars = sorted(char_count.keys(), reverse=True)
    max_length = 0
    result = ""

    for i in range(len(chars)):
        for j in range(i+1, len(chars)):
            diff = ord(chars[i]) - ord(chars[j])
            if diff >= 1:
                current_length = 2
                current_string = chars[i] + chars[j]
                last_char = chars[j]

                for k in range(j+1, len(chars)):
                    if ord(last_char) - ord(chars[k]) == diff:
                        current_length += 1
                        current_string += chars[k]
                        last_char = chars[k]

                if current_length > max_length:
                    max_length = current_length
                    result = current_string
                elif current_length == max_length and ord(chars[i]) > ord(result[0]):
                    result = chars[i] + current_string

    final_result = ""
    for char in result:
        final_result += char * char_count[char]

    return final_result

